// module github.com/fortystory/easy-look-up   模块路径：别的模块 import 你时用的前缀
// go 1.27                                     语言版本下限：决定能用哪些语法和标准库符号
// require github.com/gin-gonic/gin v1.12.0     直接依赖

// go get -u ./...                       升级依赖到最新的次版本/补丁版本
// go get example.com/mod/v2             跨主版本升级要显式写新路径
// go mod tidy                           清理 go.mod：删没用的、补漏的，不升级
// go mod edit -replace=old=new@v1.2.3    用 replace 强行改版本

// go build ./...            编译所有包，只做编译检查，不留产物
// go build -o app .        编译当前目录的 main 包，产物写到 app
// go run . -flag           编译并直接运行，用临时二进制，跑完即删
// go install ./cmd/x       编译并把命令装到 $GOBIN
// go install pkg@version   装与当前模块无关的工具，不碰 go.mod

// GOOS=windows GOARCH=amd64 go build -o app.exe ./cmd/app   交叉编译
// go tool dist list                                          列出所有支持的目标
// go env GOOS GOARCH                                         看当前默认值
// CGO_ENABLED=0 GOOS=linux GOARCH=arm64 go build ./cmd/app    纯 Go 交叉编译

// pkg/
// ├── user.go            所有平台都编译
// ├── user_windows.go    只在 GOOS=windows 编译
// ├── user_linux.go      只在 GOOS=linux 编译
// ├── user_test.go       测试文件，不进正式产物
// └── user_linux_test.go 既是测试文件，又只在 linux 编译

// iota 在常量块里从 0 开始，每行加一
const (
	KB = 1 << (10 * (iota + 1))
	MB
	GB
)

func main() {
	fmt.Println(KB, MB, GB)
}

// go test -race ./...                 开启数据竞争检测
// go test -coverprofile=c.out ./...   生成覆盖率文件
// go test -bench=. -benchmem ./...    跑基准测试并打印分配次数
// go test -run 'TestA|TestB' ./...   只跑名字匹配的测试
// go tool cover -html=c.out          在浏览器里看覆盖率

// 表驱动：每组输入和期望输出写在一行
cases := []struct {
	name string
	in   int
	want int
}{
	{"零", 0, 0},
	{"翻倍", 21, 42},
}

for _, c := range cases {
	if got := c.in * 2; got != c.want {
		fmt.Printf("用例 %s 失败: 得到 %d, 期望 %d\n", c.name, got, c.want)
	}
}

// 接口定义在使用方：只声明自己要用的方法
type UserStore interface {
	Find(id int) (string, error)
}

// 依赖注入：把依赖当参数传进来，测试时传假实现
func GetUserName(s UserStore) (string, error) {
	return s.Find(1)
}
